import { app, expedition, modes } from '../api/models'
import { createTextareaResizeCoordinator } from '../components/ui/AutoExpandingTextarea'

/**
 * NodeFSModule describes the subset of node:fs methods used to read fixture JSON
 * and write serialized probe results when invoked from the Go CLI profiler.
 */
export interface NodeFSModule {
  readFileSync: (filePath: string, encoding: string) => string
  writeFileSync: (filePath: string, content: string, encoding: string) => void
}

/**
 * LiveFrontendFixture matches the JSON fixture generated by internal/profile/probes_frontend.go.
 */
export interface LiveFrontendFixture {
  plan: Record<string, unknown>
  sidebarStats: Record<string, unknown>
  modesState?: Record<string, unknown>
  modes?: Array<Record<string, unknown>>
  visitedDetails: Array<Record<string, unknown>>
  heldRowIndex?: number
  dropPreviews?: Array<Record<string, unknown>>
}

/**
 * HydratedFrontendFixture holds the Wails-hydrated model instances used across
 * SSR and client reconciliation probes.
 */
export interface HydratedFrontendFixture {
  plan: expedition.PlanView
  sidebar: app.SidebarStats
  modesState: app.ModesState
  modesList: modes.Mode[]
  visitedDetails: expedition.WaypointDetails[]
  heldRowIndex: number
  dropPreviews: expedition.DropSlotPreview[]
  lastVisitedIndex: number
  lastFcArrivedIndex: number
}

/**
 * SpanNodeJSON mirrors Go profile.SpanNode for cross-process JSON serialization.
 */
export interface SpanNodeJSON {
  name: string
  location?: string
  category?: string
  calls: number
  itemsProcessed: number
  itemUnit?: string
  totalDuration: number
  selfDuration: number
  sqlDuration: number
  goCpuDuration: number
  sqlQueries: number
  rowsScanned: number
  allocBytes: number
  mallocs: number
  children?: SpanNodeJSON[]
}

/**
 * ProbeRunJSON mirrors Go profile.ProbeRun for cross-process JSON serialization.
 */
export interface ProbeRunJSON {
  mode: string
  iterations: number
  medianDuration: number
  minDuration: number
  maxDuration: number
  normalizedNsPerItem: number
  itemsPerSecond: number
  allocBytes: number
  bytesPerItem: number
  mallocs: number
  allocsPerItem: number
  sqlQueries: number
  sqlDuration: number
  goCpuDuration: number
  resultHash: string
  resultSummary: string
  rootSpan: SpanNodeJSON
}

/**
 * ProbeResultJSON mirrors Go profile.ProbeResult for cross-process JSON serialization.
 */
export interface ProbeResultJSON {
  name: string
  category: string
  description: string
  itemsProcessed: number
  itemUnit: string
  secondaryCount?: number
  secondaryUnit?: string
  cold: ProbeRunJSON
  warm: ProbeRunJSON
  hasWarm: boolean
  coldWarmMatch: boolean
  warmSpeedupPct: number
}

/**
 * msToNs converts fractional milliseconds from performance.now() into integer nanoseconds.
 */
export function msToNs(milliseconds: number): number {
  return Math.round(milliseconds * 1_000_000)
}

/**
 * computeSimpleHash computes a deterministic 32-bit FNV-1a hex digest over inputText.
 */
export function computeSimpleHash(inputText: string): string {
  let hashValue = 2166136261
  for (let index = 0; index < inputText.length; index++) {
    hashValue ^= inputText.charCodeAt(index)
    hashValue = Math.imul(hashValue, 16777619)
  }
  return (hashValue >>> 0).toString(16).padStart(8, '0')
}

/**
 * makeRenderSpan builds a leaf SpanNodeJSON entry for a measured frontend operation.
 */
export function makeRenderSpan(
  name: string,
  location: string,
  calls: number,
  itemsProcessed: number,
  itemUnit: string,
  durationNs: number,
): SpanNodeJSON {
  return {
    name,
    location,
    category: 'render',
    calls,
    itemsProcessed: Math.max(itemsProcessed, 1),
    itemUnit,
    totalDuration: durationNs,
    selfDuration: durationNs,
    sqlDuration: 0,
    goCpuDuration: durationNs,
    sqlQueries: 0,
    rowsScanned: 0,
    allocBytes: 0,
    mallocs: 0,
  }
}

/**
 * buildProbeRun executes executeStep for iterations passes and aggregates median,
 * min, max, and normalized per-item durations into a ProbeRunJSON record.
 */
export function buildProbeRun(
  mode: string,
  rootName: string,
  location: string,
  itemsProcessed: number,
  itemUnit: string,
  iterations: number,
  executeStep: () => { summary: string; hashInput: string; children: SpanNodeJSON[] },
): ProbeRunJSON {
  const durationsNs: number[] = []
  let lastSummary = ''
  let lastHash = ''
  let lastChildren: SpanNodeJSON[] = []

  for (let iter = 0; iter < iterations; iter++) {
    const startMs = performance.now()
    const stepOutcome = executeStep()
    const elapsedNs = msToNs(performance.now() - startMs)
    durationsNs.push(elapsedNs)
    lastSummary = stepOutcome.summary
    lastHash = computeSimpleHash(stepOutcome.hashInput)
    lastChildren = stepOutcome.children
  }

  durationsNs.sort((left, right) => left - right)
  const medianNs = durationsNs[Math.floor(durationsNs.length / 2)] ?? 0
  const minNs = durationsNs[0] ?? 0
  const maxNs = durationsNs[durationsNs.length - 1] ?? 0

  let childrenSumNs = 0
  for (const child of lastChildren) {
    childrenSumNs += child.totalDuration
  }
  const selfNs = Math.max(0, medianNs - childrenSumNs)
  const safeItems = Math.max(itemsProcessed, 1)
  const nsPerItem = medianNs / safeItems
  const itemsPerSecond = medianNs > 0 ? (safeItems * 1_000_000_000) / medianNs : 0

  return {
    mode,
    iterations,
    medianDuration: medianNs,
    minDuration: minNs,
    maxDuration: maxNs,
    normalizedNsPerItem: nsPerItem,
    itemsPerSecond,
    allocBytes: 0,
    bytesPerItem: 0,
    mallocs: 0,
    allocsPerItem: 0,
    sqlQueries: 0,
    sqlDuration: 0,
    goCpuDuration: medianNs,
    resultHash: lastHash,
    resultSummary: lastSummary,
    rootSpan: {
      name: rootName,
      location,
      category: 'render',
      calls: 1,
      itemsProcessed: safeItems,
      itemUnit,
      totalDuration: medianNs,
      selfDuration: selfNs,
      sqlDuration: 0,
      goCpuDuration: medianNs,
      sqlQueries: 0,
      rowsScanned: 0,
      allocBytes: 0,
      mallocs: 0,
      children: lastChildren,
    },
  }
}

/**
 * hydrateFrontendFixture hydrates raw fixture JSON into Wails TypeScript model instances
 * and computes true row-array frontier indices matching ExpeditionPlanner.
 */
export function hydrateFrontendFixture(parsedFixture: LiveFrontendFixture): HydratedFrontendFixture {
  const plan = expedition.PlanView.createFrom(parsedFixture.plan)
  const sidebar = app.SidebarStats.createFrom(parsedFixture.sidebarStats)
  const rawDetails = Array.isArray(parsedFixture.visitedDetails) ? parsedFixture.visitedDetails : []
  const visitedDetails = rawDetails.map((item) => expedition.WaypointDetails.createFrom(item))

  const modesState = parsedFixture.modesState
    ? app.ModesState.createFrom(parsedFixture.modesState)
    : app.ModesState.createFrom({
        modes: (Array.isArray(parsedFixture.modes) ? parsedFixture.modes : []).map((item) =>
          modes.Mode.createFrom(item),
        ),
      })
  const modesList = modesState.modes?.length ? modesState.modes : (plan.modes ?? [])

  const rawPreviews = Array.isArray(parsedFixture.dropPreviews) ? parsedFixture.dropPreviews : []
  const dropPreviews = rawPreviews.map((item) => expedition.DropSlotPreview.createFrom(item))
  const heldRowIndex = typeof parsedFixture.heldRowIndex === 'number' ? parsedFixture.heldRowIndex : -1

  let lastVisitedIndex = -1
  let lastFcArrivedIndex = -1
  if (plan.expedition.status !== 'planning') {
    ;(plan.rows ?? []).forEach((rowView, rowIndex) => {
      if (rowView.visitState === 'visited') {
        lastVisitedIndex = rowIndex
      }
      if (rowView.row.rowType === 'waypoint' && rowView.row.fcStop && rowView.row.fcArrived) {
        lastFcArrivedIndex = rowIndex
      }
    })
  }

  return {
    plan,
    sidebar,
    modesState,
    modesList,
    visitedDetails,
    heldRowIndex,
    dropPreviews,
    lastVisitedIndex,
    lastFcArrivedIndex,
  }
}

/**
 * installWailsProfileMocks installs deterministic in-memory Wails backend bindings
 * and clipboard stubs on globalThis so client-mounted hooks resolve synchronously.
 */
export function installWailsProfileMocks(visitedDetails: expedition.WaypointDetails[]): void {
  const detailsByRowId = new Map<number, expedition.WaypointDetails>()
  for (const detail of visitedDetails) {
    detailsByRowId.set(detail.rowId, detail)
  }

  const globalTarget = globalThis as unknown as {
    IS_REACT_ACT_ENVIRONMENT?: boolean
    go?: {
      app?: {
        App?: Record<string, (...args: unknown[]) => Promise<unknown>>
      }
    }
  }
  globalTarget.IS_REACT_ACT_ENVIRONMENT = true
  globalTarget.go = {
    app: {
      App: {
        GetActiveCarrierRoute: () => Promise.resolve(null),
        GetWaypointDetails: (rowId: unknown) => {
          const numericId = typeof rowId === 'number' ? rowId : 0
          return Promise.resolve(
            detailsByRowId.get(numericId) ??
              expedition.WaypointDetails.createFrom({ rowId: numericId, kind: 'leg', number: 1 }),
          )
        },
        GetRegionOptions: () =>
          Promise.resolve({
            anchorId: 18,
            anchorName: 'Inner Orion Spur',
            anchorIsDefault: true,
            suggestedRegionId: 0,
            options: [],
          }),
      },
    },
  }

  if (typeof navigator !== 'undefined' && !navigator.clipboard) {
    Object.defineProperty(navigator, 'clipboard', {
      configurable: true,
      value: {
        writeText: () => Promise.resolve(),
      },
    })
  }
}

/**
 * runTextareaBatchCoordinatorPass benchmarks the 3-phase batched measurement pass of
 * createTextareaResizeCoordinator across all POI and flight-notes values in rows.
 */
export function runTextareaBatchCoordinatorPass(rows: expedition.RowView[]): number {
  const coordinator = createTextareaResizeCoordinator()
  const mockElements: HTMLTextAreaElement[] = []

  for (const rowView of rows) {
    if (rowView.row.rowType !== 'waypoint') continue
    for (const cellText of [rowView.row.poiName ?? '', rowView.row.notes ?? '']) {
      let assignedHeight = ''
      let assignedOverflow = ''
      const estimatedLines = Math.max(1, Math.ceil(Math.max(cellText.length, 1) / 28))
      const simulatedScrollHeight = estimatedLines * 20 + 6
      const mockTextarea = {
        value: cellText,
        isConnected: true,
        offsetHeight: 28,
        clientHeight: 26,
        scrollHeight: simulatedScrollHeight,
        clientWidth: 200,
        style: {
          get height() {
            return assignedHeight
          },
          set height(nextValue: string) {
            assignedHeight = nextValue
          },
          get overflowY() {
            return assignedOverflow
          },
          set overflowY(nextValue: string) {
            assignedOverflow = nextValue
          },
        },
      } as unknown as HTMLTextAreaElement
      mockElements.push(mockTextarea)
      coordinator.scheduleMeasure(mockTextarea, 3)
    }
  }

  coordinator.flushPendingMeasures()
  let measuredWithHeightCount = 0
  for (const element of mockElements) {
    if (element.style.height !== '') {
      measuredWithHeightCount++
    }
  }
  return measuredWithHeightCount
}

